import{_ as a,o as i,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const s=JSON.parse('{"title":"脚本组件体系与能力分层深度研究","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/脚本组件体系与能力分层深度研究.md","filePath":"脚本系统/专题研究/脚本组件体系与能力分层深度研究.md","lastUpdated":1777893104000}'),h={name:"脚本系统/专题研究/脚本组件体系与能力分层深度研究.md"};function n(d,l,o,t,_,c){return i(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="脚本组件体系与能力分层深度研究" tabindex="-1">脚本组件体系与能力分层深度研究 <a class="header-anchor" href="#脚本组件体系与能力分层深度研究" aria-label="Permalink to “脚本组件体系与能力分层深度研究”">​</a></h1><p>本文基于“添加组件”与脚本编辑界面截图，对创游世界脚本/组件体系做结构性研究。</p><h2 id="_1-组件不是装饰-而是能力分发器" tabindex="-1">1. 组件不是装饰，而是能力分发器 <a class="header-anchor" href="#_1-组件不是装饰-而是能力分发器" aria-label="Permalink to “1. 组件不是装饰，而是能力分发器”">​</a></h2><p>从截图可确认，组件分为多类：</p><ul><li>通用</li><li>战斗</li><li>装置</li><li>显示</li><li>交互</li><li>自定义</li></ul><p>这说明组件在创游里不是简单标签，而是“能力入口”。</p><p>一个物体能做什么，很大程度上由它挂了什么组件决定。</p><h2 id="_2-能力分层" tabindex="-1">2. 能力分层 <a class="header-anchor" href="#_2-能力分层" aria-label="Permalink to “2. 能力分层”">​</a></h2><h3 id="_2-1-通用层" tabindex="-1">2.1 通用层 <a class="header-anchor" href="#_2-1-通用层" aria-label="Permalink to “2.1 通用层”">​</a></h3><p>典型作用：</p><ul><li>物理</li><li>可互动</li><li>开关</li><li>物体检测器</li><li>阻挡通行</li><li>等级</li><li>告示牌</li><li>物体UI</li></ul><p>这一层更像对象的基础属性与通用行为层。</p><h3 id="_2-2-战斗层" tabindex="-1">2.2 战斗层 <a class="header-anchor" href="#_2-2-战斗层" aria-label="Permalink to “2.2 战斗层”">​</a></h3><p>可见内容：</p><ul><li>生命</li><li>伤害</li><li>武器槽</li></ul><p>这说明战斗能力是可插拔的，不是所有物体天生都有血量和伤害。</p><h3 id="_2-3-装置层" tabindex="-1">2.3 装置层 <a class="header-anchor" href="#_2-3-装置层" aria-label="Permalink to “2.3 装置层”">​</a></h3><p>可见内容：</p><ul><li>地刺</li><li>怪物门</li><li>传送门</li><li>弹簧</li><li>不稳定平台</li><li>传送带</li><li>梯子</li><li>旋转</li><li>往返移动</li><li>机关组件</li></ul><p>这层负责关卡机关与环境行为。</p><h3 id="_2-4-显示层" tabindex="-1">2.4 显示层 <a class="header-anchor" href="#_2-4-显示层" aria-label="Permalink to “2.4 显示层”">​</a></h3><p>可见内容：</p><ul><li>卷轴循环</li><li>图片分身</li><li>九宫切图</li><li>描边</li><li>拖尾</li><li>粒子特效</li></ul><p>这层负责表现、渲染、视觉增强。</p><h3 id="_2-5-交互层" tabindex="-1">2.5 交互层 <a class="header-anchor" href="#_2-5-交互层" aria-label="Permalink to “2.5 交互层”">​</a></h3><p>可见内容：</p><ul><li>触摸模板</li><li>按钮</li><li>拖拽</li></ul><p>这层负责输入和交互响应。</p><h3 id="_2-6-自定义层" tabindex="-1">2.6 自定义层 <a class="header-anchor" href="#_2-6-自定义层" aria-label="Permalink to “2.6 自定义层”">​</a></h3><p>这是创作者扩展正式能力边界的入口。</p><h2 id="_3-自定义组件的真正地位" tabindex="-1">3. 自定义组件的真正地位 <a class="header-anchor" href="#_3-自定义组件的真正地位" aria-label="Permalink to “3. 自定义组件的真正地位”">​</a></h2><p>很多人会把自定义组件理解成“高级功能”，但从系统结构看，它其实更像：</p><ul><li>用户可编程扩展层</li></ul><p>因为它支持：</p><ul><li>属性</li><li>指令</li><li>触发时机</li></ul><p>这三者组合起来，已经接近一个可复用小模块。</p><h2 id="_4-组件与脚本的关系" tabindex="-1">4. 组件与脚本的关系 <a class="header-anchor" href="#_4-组件与脚本的关系" aria-label="Permalink to “4. 组件与脚本的关系”">​</a></h2><p>组件提供“这个物体拥有哪类能力”；脚本负责“这些能力在何时、如何发生”。</p><p>可以把它理解成：</p><ul><li>组件 = 能力面板</li><li>脚本 = 调度逻辑</li></ul><p>因此创游不是纯脚本系统，也不是纯组件系统，而是：</p><ul><li><strong>组件定义能力边界</strong></li><li><strong>脚本定义行为流程</strong></li></ul><h2 id="_5-为什么这种设计适合低门槛创作" tabindex="-1">5. 为什么这种设计适合低门槛创作 <a class="header-anchor" href="#_5-为什么这种设计适合低门槛创作" aria-label="Permalink to “5. 为什么这种设计适合低门槛创作”">​</a></h2><h3 id="优点-1-用户不必一次理解所有能力" tabindex="-1">优点 1：用户不必一次理解所有能力 <a class="header-anchor" href="#优点-1-用户不必一次理解所有能力" aria-label="Permalink to “优点 1：用户不必一次理解所有能力”">​</a></h3><p>不同类别拆开展示，减轻认知负担。</p><h3 id="优点-2-按玩法领域组织能力" tabindex="-1">优点 2：按玩法领域组织能力 <a class="header-anchor" href="#优点-2-按玩法领域组织能力" aria-label="Permalink to “优点 2：按玩法领域组织能力”">​</a></h3><p>战斗、装置、显示、交互天然对应不同创作任务。</p><h3 id="优点-3-给高级用户留下扩展口" tabindex="-1">优点 3：给高级用户留下扩展口 <a class="header-anchor" href="#优点-3-给高级用户留下扩展口" aria-label="Permalink to “优点 3：给高级用户留下扩展口”">​</a></h3><p>自定义组件让高级创作者能突破官方预设。</p><h2 id="_6-从研究视角看-这套体系透露了什么" tabindex="-1">6. 从研究视角看，这套体系透露了什么 <a class="header-anchor" href="#_6-从研究视角看-这套体系透露了什么" aria-label="Permalink to “6. 从研究视角看，这套体系透露了什么”">​</a></h2><h3 id="_6-1-创游内部其实很强调-对象能力组合" tabindex="-1">6.1 创游内部其实很强调“对象能力组合” <a class="header-anchor" href="#_6-1-创游内部其实很强调-对象能力组合" aria-label="Permalink to “6.1 创游内部其实很强调“对象能力组合””">​</a></h3><p>不是给你一个万能对象，而是通过挂载决定对象职责。</p><h3 id="_6-2-ui、物理、战斗、关卡机制都被统一为组件化能力" tabindex="-1">6.2 UI、物理、战斗、关卡机制都被统一为组件化能力 <a class="header-anchor" href="#_6-2-ui、物理、战斗、关卡机制都被统一为组件化能力" aria-label="Permalink to “6.2 UI、物理、战斗、关卡机制都被统一为组件化能力”">​</a></h3><p>这意味着不同系统可能共享相似的底层对象模型。</p><h3 id="_6-3-自定义组件很可能是官方提供给创作者的-轻量脚本模块系统" tabindex="-1">6.3 自定义组件很可能是官方提供给创作者的“轻量脚本模块系统” <a class="header-anchor" href="#_6-3-自定义组件很可能是官方提供给创作者的-轻量脚本模块系统" aria-label="Permalink to “6.3 自定义组件很可能是官方提供给创作者的“轻量脚本模块系统””">​</a></h3><p>这也是它价值极高的原因。</p><h2 id="_7-可继续研究的问题" tabindex="-1">7. 可继续研究的问题 <a class="header-anchor" href="#_7-可继续研究的问题" aria-label="Permalink to “7. 可继续研究的问题”">​</a></h2><ul><li>组件之间是否存在依赖关系</li><li>某些脚本块是否只有在挂载特定组件后才会出现</li><li>组件属性是否会影响脚本块可选项</li><li>UI 相关组件与显示组件之间的边界在哪里</li></ul><h2 id="_8-关键词" tabindex="-1">8. 关键词 <a class="header-anchor" href="#_8-关键词" aria-label="Permalink to “8. 关键词”">​</a></h2><ul><li>组件</li><li>通用</li><li>战斗</li><li>装置</li><li>显示</li><li>交互</li><li>自定义组件</li><li>物体UI</li><li>武器槽</li><li>粒子特效</li></ul><h2 id="_9-来源" tabindex="-1">9. 来源 <a class="header-anchor" href="#_9-来源" aria-label="Permalink to “9. 来源”">​</a></h2><ul><li><code>资料/基础写脚本界面截图/Screenshot_20260417_215321.jpg</code></li><li><code>资料/基础写脚本界面截图/Screenshot_20260417_215325.jpg</code></li><li><code>资料/基础写脚本界面截图/Screenshot_20260417_215327.jpg</code></li><li><code>资料/基础写脚本界面截图/Screenshot_20260417_215328.jpg</code></li><li><code>资料/基础写脚本界面截图/Screenshot_20260417_215329.jpg</code></li><li><code>资料/基础写脚本界面截图/Screenshot_20260417_215330.jpg</code></li><li>来源状态：历史来源路径；当前原图目录未列出可直接 OCR 的原图文件，正文依据已归档 OCR 与专题整理。</li></ul>',62)])])}const b=a(h,[["render",n]]);export{s as __pageData,b as default};
